        let gain = 0.31;

        let vx = gain * dx;
        let vy = gain * dy;
        let grip = 0;
    }

    // Near operation
    let radius = 1.0; // Example radius value
    let l1_norm = sqrt(dx*dx + dy*dy);
    let l_inf_norm = max(abs(dx), abs(dy));

    if (l1_norm <= radius || l_inf_norm <= radius) {
        vx = 0;
        vy = 0;
        grip = 0;
    } else {
        vx = 0;
        vy = 0;
        grip = 0;
    }

    // Holding operation
