        let l1_norm = abs(x) + abs(y);
        let l_inf_norm = max(abs(x), abs(y));
        let near_value = radius - l1_norm;
        if (near_value < 0) {
            near_value = 0;
        }
        vx = 0;
        vy = 0;
        grip = near_value;
    }

    // Holding operation
    else if (h == 0.5) {
        let threshold = 0.5;
        let holding_value = h - threshold;
        if (holding_value < 0) {
            holding_value = 0;
        } else if (holding_value > 1) {
            holding_value = 1;
        }
        vx = 0;
        vy = 0;
        grip = holding_value;
    }

