    else if (h == 1) {
        let close_open_value = 0;
        if (x > 0 && y > 0) {
            close_open_value = 1;
        } else if (x < 0 && y < 0) {
            close_open_value = -1;
        }
        vx = 0;
        vy = 0;
        grip = close_open_value;
    }

