```wspl
module Block {
    // Input declarations
    let x: Real[-2,2];
    let y: Real[-2,2];
    let h: Real[0,1];

    // Output declaration
    let score: Real[-8,8];

    // Move operation
    if (h == 1) {
        let gain = 1;
        let error_x = x - 0.5;
        let error_y = y - 0.5;
        let clipped_error_x = clip(error_x, -1, 1);
        let clipped_error_y = clip(error_y, -1, 1);
        let velocity_x = gain * clipped_error_x;
        let velocity_y = gain * clipped_error_y;
        score = velocity_x + velocity_y;
    }

    // Near operation
    else if (h == 0) {
        let radius = 0.5;
        let norm_xy = sqrt(x^2 + y^2);
        score = radius - norm_xy;
    }

    // Holding operation
    else if (h == 0.5) {
        let threshold = 0.5;
        score = h - threshold;
    }

    // Close/open operation
    else if (h == 0 || h == 1) {
        let amplitude = 1;
        score = 0;
    }

    // Safe operation
    else {
        let bound = 0.923;
        let norm_xy = sqrt(x^2 + y^2);
        score = bound - norm_xy;
    }
}
